(async () => {
  const until = async (fn, ms = 20000) => {
    const end = Date.now() + ms;
    while (Date.now() < end) { if (await fn()) return true; await new Promise(resolve => setTimeout(resolve,40)); }
    return false;
  };
  const assert = (value, why) => { if (!value) throw Error(why); };
  assert(await until(() => loadedModel === 'black-forest-labs/FLUX.1-Krea-dev'
    && !galleryPending && !jobListing && !busy && !submitting && !els.allModels.checked), 'fresh cold FLUX page did not settle');
  const q = window.__copyFeedback = { until, assert, calls: [], grants: [], forbidden: [], errors: [],
    native: window.fetch.bind(window), press: null, changes: [] };
  const deny = name => { q.forbidden.push(name); throw Error('UI30 synthetic fixture refused ' + name); };
  q.port = Object.freeze({
    writeText(text) {
      const grant = q.grants.find(item => !item.seen);
      assert(grant && grant.text === text, 'copy lacked its exact one-use synthetic text grant');
      assert(q.press?.isTrusted
        && q.press.target.closest('[role="menuitem"]')?.dataset.ui30 === grant.name,
        'clipboard write did not start synchronously inside its exact physical menu choice');
      grant.seen = true; grant.trusted = true;
      q.calls.push({ name: grant.name, text, trusted: true });
      return grant.promise;
    },
    write: () => deny('picture clipboard write'), read: () => deny('clipboard read'), readText: () => deny('clipboard readText'),
  });
  // Programmatic port installation does not read, preserve or restore native clipboard contents.
  Object.defineProperty(navigator, 'clipboard', { configurable: true, value: q.port });
  assert(navigator.clipboard === q.port && Object.getOwnPropertyDescriptor(navigator,'clipboard').value === q.port
    && Object.isFrozen(q.port) && q.calls.length === 0, 'synthetic clipboard installation did not verify before copying');
  document.execCommand = () => deny('execCommand');
  window.ClipboardItem = function () { return deny('native ClipboardItem'); };
  // Observe the actual trusted chooser call, not microtask timing between
  // native capture/bubble listeners. The original product action runs intact.
  const chooseCopy = chooseContextItem;
  chooseContextItem = function (li) {
    const event = window.event;
    assert(event?.type === 'click' && event.isTrusted
      && event.target?.closest('[role="menuitem"]') === li,
      'copy chooser did not receive its actual trusted menu click');
    q.press = event;
    try { return chooseCopy.call(this, li); }
    finally { q.press = null; }
  };
  addEventListener('error', event => q.errors.push(event.message));
  addEventListener('unhandledrejection', event => q.errors.push(String(event.reason)));
  q.arm = (name, text) => {
    assert(!q.grants.some(item => item.name === name), 'duplicate synthetic copy grant');
    let resolve,reject;
    const promise = new Promise((yes,no) => { resolve = yes; reject = no; });
    q.grants.push({ name,text,promise,resolve,reject,seen:false,settled:false });
  };
  q.finish = (name, error = false) => {
    const grant = q.grants.find(item => item.name === name);
    assert(grant?.seen && !grant.settled, 'synthetic completion was unused or duplicate');
    grant.settled = true;
    if (error) grant.reject(Error('synthetic UI30 copy refusal')); else grant.resolve();
  };
  q.tag = (label, tag) => {
    assert(!els.contextMenu.hidden, 'physical context menu did not open');
    const item = [...els.contextMenu.querySelectorAll('[role="menuitem"]')]
      .find(item => item.firstElementChild?.textContent === label);
    assert(item && item.getAttribute('aria-disabled') !== 'true', 'requested copy item absent or held');
    item.dataset.ui30 = tag; // Programmatic selector annotation only; the following choice is physical.
  };
  q.note = text => showError(text,true,{ slot:els.lbError,mirror:false }); // Labeled unrelated-message sentinel.
  q.read = async path => {
    const url = new URL(path,location.href);
    assert(url.origin === location.origin && url.pathname.startsWith('/api/'), 'fixture GET escaped same-origin API');
    const response = await q.native(url.href,{ method:'GET' });
    assert(response.ok, 'actual fixture GET failed ' + url.pathname); return response.json();
  };
  window.fetch = (input,options) => {
    const url = new URL(typeof input === 'string' ? input : input.url,location.href);
    const method = String(options?.method ?? (typeof input === 'string' ? 'GET' : input.method) ?? 'GET').toUpperCase();
    if (url.origin !== location.origin || method !== 'GET') return deny(method + ' ' + url.pathname);
    return q.native(input,options);
  };
  q.pngs = async () => Promise.all(q.rows.map(async row => {
    const response = await q.native(row.url,{ method:'GET',cache:'no-store' });
    assert(response.ok && response.headers.get('Content-Type')?.includes('image/png'), 'owned PNG GET failed');
    const bytes = await response.arrayBuffer();
    const hash = [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(n=>n.toString(16).padStart(2,'0')).join('');
    return { id:row.id,size:bytes.byteLength,hash };
  }));
  const page = await q.read('/api/gallery?all_models=true&limit=20');
  q.rows = [...page.items].sort((a,b)=>a.id-b.id);
  assert(page.total === 2 && q.rows.length === 2 && q.rows.every(row => row.job_id === 'planted'
    && row.run_id === 'planted' && row.model_id === 'krea/Krea-2-Turbo'), 'fixture is not exactly the two actual planted rows');
  assert((await q.read('/api/jobs?include_finished=true')).length === 0 && !currentJob
    && queuedIds.length === 0 && submissions.size === 0, 'fixture was not idle');
  q.recordBefore = JSON.stringify(q.rows); q.pngBefore = JSON.stringify(await q.pngs());
  q.panelBefore = JSON.stringify(setupComposerState());
  const onchange = els.allModels.onchange;
  els.allModels.onchange = function (...args) {
    q.changes.push({ trusted:args[0]?.isTrusted, checked:this.checked }); return onchange.apply(this,args);
  };
  return true;
})()

